// Récupérer les données depuis l'input (node précédent)
const extractCodeData = $input.first().json;
const explanation = extractCodeData.explanation;
const language = extractCodeData.language;
const fileName = extractCodeData.file_name;

console.log('=== CLEAN TEXT FOR TELEGRAM ===');

// Fonction pour échapper TOUS les caractères spéciaux de Telegram
function escapeForTelegram(text) {
  return text
    // Supprimer d'abord tous les markdown
    .replace(/```[\w]*\n?/g, '')
    .replace(/```/g, '')
    .replace(/#{1,6}\s+/g, '')
    .replace(/\*\*\*/g, '')
    .replace(/\*\*/g, '')
    .replace(/\*/g, '')
    .replace(/___/g, '')
    .replace(/__/g, '')
    .replace(/_/g, ' ')  // Remplacer par espace
    .replace(/~~~/g, '')
    .replace(/~~/g, '')
    .replace(/`/g, '')
    .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
    .replace(/<[^>]*>/g, '')
    .replace(/\\/g, '')

    // Échapper les caractères qui causent des problèmes avec Markdown
    .replace(/\[/g, '(')
    .replace(/\]/g, ')')
    .replace(/\(/g, ' ')
    .replace(/\)/g, ' ')

    // Supprimer TOUS les emojis et symboles Unicode
    .replace(/[\u{1F000}-\u{1F9FF}]/gu, '')
    .replace(/[\u{2600}-\u{26FF}]/gu, '')
    .replace(/[\u{2700}-\u{27BF}]/gu, '')

    // Remplacer les caractères spéciaux courants
    .replace(/→/g, '->')
    .replace(/←/g, '<-')
    .replace(/✓/g, 'OK')
    .replace(/✗/g, 'X')
    .replace(/•/g, '-')
    .replace(/–/g, '-')
    .replace(/—/g, '-')
    .replace(/[""]/g, '"')
    .replace(/['']/g, "'")

    // Nettoyer les espaces
    .replace(/\s{3,}/g, '  ')
    .replace(/\n{4,}/g, '\n\n')
    .trim();
}

const cleanText = escapeForTelegram(explanation);

// Limite Telegram : 4096 caractères
const MAX_LENGTH = 3500;

let finalText = cleanText;

// Tronquer si nécessaire
if (cleanText.length > MAX_LENGTH) {
  console.log('Troncature necessaire');

  const truncated = cleanText.substring(0, MAX_LENGTH);
  const lastPeriod = truncated.lastIndexOf('.');
  const lastNewline = truncated.lastIndexOf('\n');

  const cutPoint = Math.max(lastPeriod, lastNewline);

  if (cutPoint > MAX_LENGTH * 0.8) {
    finalText = truncated.substring(0, cutPoint + 1) + '\n\nSuite dans le fichier';
  } else {
    finalText = truncated.substring(0, MAX_LENGTH - 25) + '\n\nSuite dans le fichier';
  }
}

// Message ULTRA-SIMPLE sans AUCUN caractère spécial
const telegramMessage = `Code ${language} genere\n\nFichier ${fileName}\n\n${finalText}\n\nVoir fichier ci-joint`;

// Dernière vérification
const finalMessage = telegramMessage.length > 4096 
  ? telegramMessage.substring(0, 4090)
  : telegramMessage;

console.log('Message final length:', finalMessage.length);

return {
  json: {
    telegram_text: finalMessage,
    original_explanation: explanation,
    language: language,
    file_name: fileName,
    text_truncated: cleanText.length > MAX_LENGTH,
    original_length: explanation.length,
    final_length: finalMessage.length
  }
};

// Récupération rapide des données
const userMessage = $input.first().json.query || $input.first().json.message;
const userId = $input.first().json.user_id || $input.first().json.sessionId || 'default_user';
const lastCode = $input.first().json.value || null;

// Détection rapide du type de requête
const isModification = /modif|change|corrige|améliore|ajuste|update|fix|bug|ajoute|supprime|remplace/i.test(userMessage);

let userPrompt = userMessage;

// Modification de code (amélioré)
if (isModification && lastCode) {
  try {
    const code = JSON.parse(lastCode);
    userPrompt = `📌 MODIFICATION DU CODE PRÉCÉDENT

**Code actuel (${code.language}):**
\`\`\`${code.language}
${code.code}
\`\`\`

**Requête originale:** ${code.original_request}

**Date de création:** ${new Date(code.timestamp).toLocaleString('fr-FR')}

---

**🔄 MODIFICATION DEMANDÉE:** ${userMessage}

⚠️ **IMPORTANT:** Fournis le code COMPLET modifié dans un bloc de code formaté avec \`\`\`${code.language}.
Ne fournis PAS seulement les parties modifiées, mais tout le code complet et fonctionnel.`;
  } catch (e) {
    console.log('Erreur parsing last code:', e);
  }
}

return {
  json: {
    user_id: userId,
    user_message: userMessage,
    user_prompt: userPrompt,
    has_previous_code: lastCode !== null,
    is_modification: isModification
  }
};

// Extraire le code de la réponse
const response = $input.first().json.output;
const prepareContext = $('Préparer Contexte').first().json;
const userId = prepareContext.user_id;
const userMessage = prepareContext.user_message;

console.log('=== DEBUG EXTRAIRE CODE ===');
console.log('User Message:', userMessage);
console.log('Response length:', response.length);

// Regex pour extraire le code et le langage
const codeBlockRegex = /```(\w+)?\n([\s\S]*?)```/g;
let matches = [...response.matchAll(codeBlockRegex)];

let extractedCode = '';
let language = 'bash'; // Défaut bash
let explanation = response;

if (matches.length > 0) {
  language = matches[0][1] || 'bash';
  extractedCode = matches[0][2].trim();

  console.log('✅ Code trouvé - Language:', language);
  console.log('Code length:', extractedCode.length);

  const splitResponse = response.split('```');
  explanation = splitResponse[0].trim();

  if (splitResponse.length > 2) {
    const afterCode = splitResponse.slice(2).join('').trim();
    if (afterCode) {
      explanation += '\n\n' + afterCode;
    }
  }
} else {
  console.log('⚠️ Aucun bloc de code trouvé');
  // Deviner le langage depuis la requête
  if (/python/i.test(userMessage)) language = 'python';
  else if (/javascript|node/i.test(userMessage)) language = 'javascript';
  else if (/powershell/i.test(userMessage)) language = 'powershell';
  else if (/sql/i.test(userMessage)) language = 'sql';
}

// Fonction de génération du nom de fichier intelligent
function generateFileName(query, lang) {
  if (!query || typeof query !== 'string') query = 'script';
  if (!lang || typeof lang !== 'string') lang = 'bash';

  // Stop words français
  const stopWords = ['le', 'la', 'les', 'un', 'une', 'des', 'de', 'du', 'pour', 'avec', 'dans', 'sur', 'et', 'ou', 'mais', 'qui', 'que', 'quoi', 'comment', 'créer', 'faire', 'script', 'code', 'programme', 'écris', 'écrire', 'creer', 'bash', 'python', 'javascript', 'sql', 'powershell'];

  // Extraire les mots significatifs (max 5)
  const words = query
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '') // Enlever accents
    .replace(/[^a-z0-9\s]/g, '') // Garder lettres et chiffres
    .split(/\s+/)
    .filter(word => word.length > 2 && !stopWords.includes(word))
    .slice(0, 5);

  let keywords = words.length > 0 ? words.join('_') : 'script';
  keywords = keywords.substring(0, 40); // Limiter longueur

  // Extensions par langage
  const fileExtensions = {
    'python': '.py',
    'javascript': '.js',
    'bash': '.sh',
    'shell': '.sh',
    'powershell': '.ps1',
    'sql': '.sql',
    'typescript': '.ts',
    'php': '.php',
    'ruby': '.rb',
    'go': '.go',
    'rust': '.rs'
  };

  const fileExtension = fileExtensions[lang.toLowerCase()] || '.sh';
  return `${lang.toLowerCase()}_${keywords}${fileExtension}`;
}

const codeData = {
  code: extractedCode,
  language: language,
  explanation: explanation,
  timestamp: new Date().toISOString(),
  original_request: userMessage,
  version: 1
};

const fileName = generateFileName(userMessage, language);

return {
  json: {
    user_id: userId,
    code: extractedCode,
    language: language,
    explanation: explanation,
    full_response: response,
    code_data_string: JSON.stringify(codeData),
    formatted_response: `${explanation}\n\n\`\`\`${language}\n${extractedCode}\n\`\`\``,
    file_name: fileName,
    file_extension: fileName.split('.').pop(),
    has_code: extractedCode.length > 0
  }
};

// Récupérer les données du code depuis "Extraire Code"
const extractCodeData = $('Extraire Code').first().json;
const code = extractCodeData.code || '# Code vide';
const fileName = extractCodeData.file_name;
const language = extractCodeData.language || 'bash';
const explanation = extractCodeData.explanation || 'Code généré';

console.log('=== CREATE TEXT FILE ===');
console.log('File name:', fileName);
console.log('Language:', language);
console.log('Code length:', code.length);

// Shebang et commentaire selon le langage
let shebang = '';
let commentChar = '#';

switch(language.toLowerCase()) {
  case 'bash':
  case 'shell':
    shebang = '#!/usr/bin/env bash';
    commentChar = '#';
    break;
  case 'python':
    shebang = '#!/usr/bin/env python3';
    commentChar = '#';
    break;
  case 'powershell':
    shebang = '';
    commentChar = '#';
    break;
  case 'javascript':
  case 'typescript':
    shebang = '#!/usr/bin/env node';
    commentChar = '//';
    break;
  case 'php':
    shebang = '#!/usr/bin/env php';
    commentChar = '//';
    break;
  case 'ruby':
    shebang = '#!/usr/bin/env ruby';
    commentChar = '#';
    break;
  default:
    shebang = '';
    commentChar = '#';
}

// Construire le contenu du fichier
const fileContent = `${shebang ? shebang + '\n' : ''}${commentChar} Fichier généré par AI Coder Agent
${commentChar} Langage: ${language}
${commentChar} Date: ${new Date().toISOString()}
${commentChar} Nom: ${fileName}
${commentChar}
${commentChar} ${explanation.split('\n')[0]}

${code}`;

console.log('File content length:', fileContent.length);

// Créer un objet binaire pour Telegram
const buffer = Buffer.from(fileContent, 'utf-8');

return {
  json: {
    file_name: fileName,
    language: language,
    file_size: buffer.length
  },
  binary: {
    file: {
      data: buffer.toString('base64'),
      mimeType: 'text/plain',
      fileName: fileName,
      fileExtension: fileName.split('.').pop()
    }
  }
};

