const currentData = extractCodeData.code_data_string;
const userId = extractCodeData.user_id;

// Récupérer l'historique existant depuis Redis - Get History
const existingHistoryStr = $input.first().json.value || null;

let history = { codes: [], count: 0, last_updated: new Date().toISOString() };

// Récupérer l'historique existant
if (existingHistoryStr) {
  try {
    history = JSON.parse(existingHistoryStr);
  } catch (e) {
    console.log('Erreur parsing history:', e);
    history = { codes: [], count: 0, last_updated: new Date().toISOString() };
  }
}

// Ajouter le nouveau code au début
history.codes.unshift(currentData);

// Garder les 20 derniers codes
history.codes = history.codes.slice(0, 20);
history.count = history.codes.length;
history.last_updated = new Date().toISOString();

return {
  json: {
    user_id: userId,
    history_string: JSON.stringify(history)
  }
};

