={{ 
  const historyData = $json.value ? JSON.parse($json.value) : { codes: [], count: 0 };
  let formattedHistory = `📚 **Historique de vos codes** (${historyData.count} codes sauvegardés)\n\n`;

  if (historyData.codes && historyData.codes.length > 0) {
    historyData.codes.forEach((codeStr, index) => {
      try {
        const code = JSON.parse(codeStr);
        formattedHistory += `**${index + 1}. ${code.language.toUpperCase()}** - ${new Date(code.timestamp).toLocaleString('fr-FR')}\n`;
        formattedHistory += `   Requête: ${code.original_request.substring(0, 80)}${code.original_request.length > 80 ? '...' : ''}\n\n`;
      } catch (e) {
        console.log('Erreur parsing code:', e);
      }
    });
  } else {
    formattedHistory += 'Aucun code dans l\'historique.';
  }

  return formattedHistory;
}}

